--exec sp_DanhSachHopDongKyMoi '2000-3-1','2019-10-30','test','StaffOneYear'
CREATE PROCEDURE [dbo].[sp_DanhSachHopDongKyMoi]
	-- Add the parameters for the stored procedure here
	@fromdate datetime,
	@todate datetime,
	@UserName nvarchar(50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	--xoa hop dong cu
	
	DELETE SmartBooks_ContractList where CL_StartDate between @fromdate and @todate
										and InsertSource=N'AutoGenerated'
	DECLARE @Employee_ID nvarchar(50),@StartedDate datetime,@ProbationDate datetime,@ContractFlow nvarchar(50),@Contract_ID nvarchar(50)
			,@NumberOfMonth float,@NumberOfDay int,@NumberOfYear float,@CL_StartDate datetime,@CL_ExpiredDate datetime
			,@isOnlyWorkingDay bit
			,@dnext datetime
	--LẤY LUỒNG HĐ
	IF OBJECT_ID('tempdb..#tmp_ContractFlow') IS NOT NULL DROP TABLE #tmp_ContractFlow
	SELECT Employee_ID,
	(case when ISNULL(empl.ContractFlow,'')<>'' then empl.ContractFlow else 
	(case when isnull(posc.ContractFlow,'')<>'' then posc.ContractFlow else
	(case when isnull(pos.ContractFlow,'')<>'' then pos.ContractFlow else
	(case when isnull(team.ContractFlow,'')<>'' then team.ContractFlow else
	(case when isnull(sect.ContractFlow,'')<>'' then sect.ContractFlow else
	(case when isnull(dept.ContractFlow,'')<>'' then dept.ContractFlow
	end)end)end)end)end)end) as ContractFlow
		INTO #tmp_ContractFlow
	FROM
	Smartbooks_Employee empl
	left join
	SmartBooks_Department dept
	on empl.DepartmentCode=dept.DepartmentCode
	left join
	SmartBooks_Section sect
	on empl.SectionCode=sect.SectionCode
	left join
	SmartBooks_Team team
	on empl.TeamCode=team.TeamCode
	left join
	SmartBooks_Position pos
	on empl.Position_ID=pos.Position_ID
	left join
	SmartBooks_PositionCategory posc
	on empl.PositionCategory_ID=posc.PositionCategory_ID

	CREATE NONCLUSTERED INDEX IX
    ON #tmp_ContractFlow (Employee_ID);
	
	--
	DECLARE cur CURSOR LOCAL FOR    
	select empl.Employee_ID,empl.StartedDate,empl.OfficialDate
	,cf.ContractFlow
	from
	SmartBooks_Employee empl
	left join
	#tmp_ContractFlow cf
	on empl.Employee_ID=cf.Employee_ID
	where StartedDate<=@todate
	and (TernimationDate is null or TernimationDate>@todate)
	--and empl.Employee_ID in ('1401002','1401003','1401005','1401007','1401010','1401011','1401012','1402001','1402002','1402004','1402005','1402006','1402007','1402008','1402010','1402014','1402015','1402016','1402017','1402018','1402024','1402025','1402026','1402027','1402029','1402030','1402031','1402035','1402037','1402038','1402039','1402040','1402043','1402047','1402048','1402050','1402051','1402052','1402053','1402054','1402055','1402057','1402058','1402059','1402062','1402063','1402064','1402065','1402066','1402067','1402071','1402072','1402073','1402074','1402075','1402076','1402077','1402078','1402080','1402081','1402082','1402083','1402084','1402086','1402088','1402090','1402091','1402092','1402093','1402094','1402096','1402101','1402102','1402103','1402104','1402105','1402106','1402108','1402109','1402111','1402112','1402113','1402115','1402116','1402117','1402118','1402119','1402120','1402122','1402123','1402124','1402125','1402126','1402128','1402129','1402130','1402131','1402132','1402133','1402134','1403001','1403002','1403003','1403004','1403005','1403006','1403007','1403009','1403010','1403013','1403016','1403018','1403021','1403022','1403023','1403025','1403026','1403028','1403029','1403031','1403032','1403033','1403035','1403036','1403038','1403040','1403041','1403043','1403044','1403045','1403046','1403047','1403048','1403049','1403050','1403051','1403052','1403053','1403054','1403056','1403057','1403058','1403060','1403061','1403062','1403063','1403064','1403065','1403066','1403067','1403068','1403069','1403070','1403071','1403072','1403073','1403074','1403075','1403076','1403078','1403081','1403082','1403083','1403084','1403085','1403086','1403087','1403089','1403091','1403092','1403094','1403095','1403097','1403098','1403099','1403101','1403102','1403103','1403105','1403106','1403107','1403108','1403109','1403111','1404001','1404002','1404004','1404005','1404006','1404007','1404008','1404012','1404014','1404015','1404016','1404017','1404018','1404019','1404020','1404021','1404023','1404024','1404025','1404026','1404027','1404028','1404029','1404030','1404031','1404032','1404033','1404035','1404037','1404038','1404039','1404040','1404041','1404042','1404043','1404044','1404045','1404046','1404047','1404048','1404049','1404051','1404054','1404055','1404057','1404058','1404060','1404061','1404063','1404064','1405001','1405002','1405004','1405005','1405006','1405007','1405008','1405009','1405010','1405011','1405012','1405013','1405014','1405016','1405017','1405018','1405019','1405020','1405021','1405022','1405023','1405024','1405025','1405026','1405028','1405029','1405030','1405031','1405032','1405033','1405035','1405036','1405037','1406001','1406002','1406003','1406004','1406005','1406006','1406007','1406008','1406009','1406011','1406012','1406013','1406015','1406016','1406017','1406018','1406019','1406020','1406021','1406022','1406023','1406025','1406026','1406028','1406029','1406030','1406031','1406033','1406034','1406036','1406037','1406038','1406039','1406041','1406042','1406043','1406045','1406046','1406047','1406048','1406049','1406050','1406051','1406052','1406054','1406055','1406056','1406057','1406059','1406060','1406061','1406062','1406063','1406064','1406065','1406066','1406067','1406068','1406069','1406071','1406072','1406073','1406074','1406075','1406078','1406079','1406080','1406081','1406084','1406085','1406086','1406087','1406088','1406089','1407002','1407003','1407004','1407005','1407007','1407008','1407010','1407011','1407012','1407013','1407014','1407017','1407018','1407020','1407021','1407022','1407023','1407025','1407026','1407028','1407029','1407030','1407031','1407032','1407033','1407035','1407036','1407037','1407039','1407040','1407041','1407044','1407045','1407047','1407048','1407049','1407051','1407052','1407053','1407054','1407055','1407056','1407057','1407058','1407061','1407062','1407063','1407064','1407066','1407067','1407069','1407072','1407073','1407074','1407075','1407076','1407077','1407078','1407079','1407080','1407081','1407082','1407083','1407085','1407086','1407088','1407090','1407091','1407092','1407093','1407094','1407095','1407096','1407097','1407101','1407102','1407103','1407106','1407107','1407108','1407109','1407110','1407111','1407114','1407115','1407116','1407117','1407118','1407120','1407121','1407122','1407123','1408001','1408002','1408003','1408004','1408005','1408006','1408008','1408009','1408010','1408011','1408012','1408013','1408015','1408017','1408018','1408019','1408023','1408025','1408029','1408030','1408032','1408033','1408034','1408036','1408038','1408039','1408040','1409001','1409003','1409005','1409007','1409008','1409011','1409013','1409014','1409015','1409016','1409017','1409018','1409019','1409021','1409022','1409023','1409025','1409026','1409027','1409030','1409033','1409034','1409035','1409036','1409037','1409038','1409039','1409040','1409041','1409042','1409043','1409044','1409046','1409047','1409049','1409050','1409051','1410001','1410002','1410003','1410004','1410006','1410007','1410008','1410010','1410012','1410014','1410015','1410016','1410017','1410018','1410021','1410022','1410024','1410025','1410026','1410027','1410028','1410029','1410030','1410031','1410033','1410037','1410038','1410039','1410040','1410041','1410042','1410043','1410044','1410045','1410046','1410047','1410048','1410049','1410051','1410052','1410054','1410055','1410056','1410057','1410058','1410059','1410060','1410061','1410063','1410065','1410067','1410068','1410071','1410072','1410074','1410075','1410076','1410077','1410079','1410081','1410082','1410083','1410085','1410086','1410091','1410092','1410094','1410095','1411001','1411002','1411004','1411005','1411006','1411007','1411010','1411011','1411012','1411013','1411014','1411016','1411018','1411020','1411022','1411023','1411027','1411028','1411029','1411030','1411031','1411032','1411033','1411035','1411036','1411039','1411041','1411042','1411043','1411044','1411045','1411046','1411047','1411048','1411049','1411051','1411052','1411054','1411055','1411056','1411057','1411058','1411059','1411060','1411061','1411062','1412001','1412003','1412004','1412005','1412006','1412007','1412009','1412010','1412011','1412012','1412013','1412015','1412017','1412018','1412020','1412021','1412022','1412023','1412024','1412028','1412029','1412031','1412032','1412034','1412035','1412036','1412037','1412038','1412039','1412040','1412042')
	--and empl.Employee_ID='1804099'
	 OPEN  cur     
	 FETCH NEXT FROM cur INTO @Employee_ID,@StartedDate,@ProbationDate,@ContractFlow
	 WHILE @@FETCH_STATUS = 0    
	 BEGIN
		set @CL_StartDate=@StartedDate
		set @CL_ExpiredDate=@CL_StartDate
		DECLARE cur_ContractFlow CURSOR LOCAL FOR
		select Contract_ID from HR_ContractFlow where ContractFlow=@ContractFlow order by No_
		OPEN  cur_ContractFlow     
		 FETCH NEXT FROM cur_ContractFlow INTO @Contract_ID
		 WHILE @@FETCH_STATUS = 0    
		 BEGIN
			if @CL_StartDate>@todate break --THOÁT KHỎI VÒNG LẶP NẾU THỜI GIAN KÝ VƯỢT KHUNG GIỜ
			--TÍNH THỜI GIAN HẾT HẠN HĐ
			select @NumberOfDay=NumberOfDay,@NumberOfMonth=NumberOfMonth,@NumberOfYear=NumberOfYear,@isOnlyWorkingDay=isOnlyWorkingDay from SmartBooks_Contract where Contract_ID=@Contract_ID
			if isnull(@NumberOfDay,0)=0 and isnull(@NumberOfMonth,0)=0 and isnull(@NumberOfYear,0)=0 begin
				set @CL_ExpiredDate=null
			end else begin
				set @CL_ExpiredDate=DATEADD(day,isnull(@NumberOfDay,0),DATEADD(MONTH,isnull(@NumberOfMonth,0),DATEADD(YEAR,isnull(@NumberOfYear,0),@CL_ExpiredDate)))
				if @isOnlyWorkingDay=1 begin
					set @dnext=@CL_ExpiredDate
					while [dbo].[udf_CountWorkingDay](@CL_StartDate,@dnext)=@NumberOfDay begin
						set @dnext=@dnext+1
						set @CL_ExpiredDate=@dnext
					end
				end
			end
			
			--KIỂM TRA LƯU HĐ
			if @CL_StartDate between @fromdate and @todate begin
				if not exists(select * from SmartBooks_ContractList where Employee_ID=@Employee_ID and CL_StartDate=@CL_StartDate) begin
					insert into SmartBooks_ContractList(Employee_ID,CL_RegisterDate,CL_StartDate,CL_ExpiredDate,[Type],InsertSource,UserName,InsertDate)
					values(@Employee_ID,@CL_StartDate,@CL_StartDate,@CL_ExpiredDate-1,@Contract_ID,N'AutoGenerated',@UserName,GETDATE())
				end
			end
			--GÁN NGÀY KÝ HĐ TIẾP THEO
			set @CL_StartDate=@CL_ExpiredDate
		 FETCH NEXT FROM cur_ContractFlow INTO @Contract_ID
		 END    
		 CLOSE cur_ContractFlow    
		 DEALLOCATE cur_ContractFlow   
	 FETCH NEXT FROM cur INTO @Employee_ID,@StartedDate,@ProbationDate,@ContractFlow    
	 END    
	 CLOSE cur    
	 DEALLOCATE cur 
	 select N'Thực hiện thành công!' as ThongBao
END

